// One PublishRequest per channel slot, with a deterministic idempotency key so a replayed
// run cannot double-post. The key is the whole reason a retry is safe here.
const crypto = require('crypto');
const e = $('Envelope In').first().json;
const p = e.payload;
const reqs = (p.slots || []).map((slot, i) => {
  const content = (p.copy || []).find(c => c.slot?.channel === slot.channel && c.slot?.format === slot.format) || (p.copy || [])[i] || {};
  const assets = (p.assets || []).filter(a => !a.channel_fit || a.channel_fit.includes(slot.channel));
  const body = [content.hook, content.body].filter(Boolean).join('\n\n');
  const key = crypto.createHash('sha256').update([e.tenant_id, slot.channel, slot.format, body, assets.map(a => a.asset_id).join(',')].join('|')).digest('hex');
  return {
    request_id: 'pub_' + key.slice(0, 16),
    tenant_id: e.tenant_id,
    brand_id: e.brand_id,
    trace_id: e.trace_id,
    channel: slot.channel,
    format: slot.format,
    account_ref: p.accounts?.[slot.channel] || null,
    content: { title: content.title || null, body, caption: content.caption || content.body || null, hashtags: content.hashtags || [], link: content.link || null, alt_text: content.alt_text || null, first_comment: content.first_comment || null, asset_ids: assets.map(a => a.asset_id), asset_urls: assets.map(a => a.public_url) },
    schedule: p.schedule || { mode: 'now' },
    gates: p.gates || {},
    idempotency_key: key,
    dry_run: p.dry_run === true
  };
});
return reqs.map(r => ({ json: r }));

// Partial success is a normal outcome, not an error. Report exactly what went out and what
// did not, so a human fixes one channel instead of re-running a whole campaign.
const items = $input.all().map(i => i.json);
const ok = items.filter(x => x.published_at && !x.error);
const failed = items.filter(x => x.error);
return [{ json: {
  published: ok.map(x => ({ channel: x.channel, external_id: x.external_id, url: x.url || null })),
  failed: failed.map(x => ({ channel: x.channel, code: x.error.code, message: x.error.message })),
  status: failed.length === 0 ? 'complete' : (ok.length ? 'partial' : 'failed'),
  published_count: ok.length,
  failed_count: failed.length
} }];
